import { Component, OnInit } from '@angular/core';
import { HttpClient } from '@angular/common/http';

@Component({
  selector: 'app-leave-tracker',
  templateUrl: './leave-tracker.component.html',
  styleUrls: ['./leave-tracker.component.css']
})
export class LeaveTrackerComponent implements OnInit {
  leaves: any[] = [];  // ✅ Define 'leaves' as an array
  employeeId: number = 1;  // Change dynamically if needed

  constructor(private http: HttpClient) {}

  ngOnInit() {
    this.getLeaveRecords();
  }

  getLeaveRecords() {
      console.log("Fetching leave records for Employee ID:", this.employeeId);  // ✅ Debugging log
    this.http.get<any[]>(`http://localhost:5000/api/leave/${this.employeeId}`)
      .subscribe(response => {
        this.leaves = response;  // ✅ Assign API response to `leaves`;
        console.log("Leave Data:", this.leaves);  // Debugging Log
      }, error => {
        console.error("Error fetching leave balance:", error);
      });
  }

  // ✅ HR Approval/Rejection Logic
  updateLeaveStatus(leaveId: number, status: string) {
    console.log(`Updating leave ${leaveId} to status: ${status}`);
    this.http.put(`http://localhost:5000/api/leave/${leaveId}`, status, { responseType: 'text' })
      .subscribe(response => {
        console.log("Success:",response);
        alert(`Leave ${status} successfully!`);
        this.getLeaveRecords();  // Refresh list after update
      }, error => {
        console.error("Error updating leave status:", error);
        alert("Failed to update leave status.");
      });
    }
}
<h2>Leave Tracker</h2>

<table border="1">
  <tr>
    <th>Employee ID</th>
    <th>Leave Type</th>
    <th>Start Date</th>
    <th>End Date</th>
    <th>Status</th>
  </tr>
  <tr *ngFor="let leave of leaves">
    <td>{{ leave.employeeId }}</td>
    <td>{{ leave.leaveType }}</td>
    <td>{{ leave.startDate }}</td>
    <td>{{ leave.endDate }}</td>
    <td>{{ leave.status }}</td>
    <td>
      <button (click)="updateLeaveStatus(leave.id, 'Approved')">✅ Approve</button>
      <button (click)="updateLeaveStatus(leave.id, 'Rejected')">❌ Reject</button>
    </td>
  </tr>
</table>
